select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"native_identity_key":"nlscale:20261102:ol:OL15261049W"},"seq":1,"relation":"works","after_row":{"id":987149001,"title":"Wittgenstein","cover_id":null,"author_id":969300005,"work_type":"collection","source_type":"open_library","open_library_id":"OL15261049W","first_publish_year":1990,"native_identity_key":"nlscale:20261102:ol:OL15261049W"},"before_row":null},{"key":{"open_library_edition_id":"OL1610479M"},"seq":2,"relation":"editions","after_row":{"id":987249001,"title":"Wittgenstein","isbn_10":null,"isbn_13":"9789023431923","work_id":987149001,"cover_id":null,"language":"dut","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL1610479M"},"before_row":null},{"key":{"work_id":987149001,"language":"nl"},"seq":3,"relation":"catalog_work_descriptions","after_row":{"text":"Willem Frederik Hermans onderzoekt in deze bundel het leven en de denkbeelden van Ludwig Wittgenstein. Hij verbindt een biografische benadering met beschouwingen over diens filosofie en met kritiek op de manier waarop anderen die uitleggen. De verzamelde stukken ontstonden op verschillende momenten en laten ook Hermans als lezer en polemist zien. Daarbij gaat het niet om één doorlopende levensbeschrijving, maar om essays en reacties waarin filosofische vragen, interpretatie en persoonlijke betrokkenheid naast elkaar staan.","work_id":987149001,"evidence":[{"note":"Original1990collectedWittgensteinessays, distinct1967standaloneandHermansTractatustranslation; preciseDutchPaperback9789023431923.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p067203663"],"reference":"new-work-dossier-readings-050.json#187","checked_at":"2026-11-03T10:41:36.494Z"},{"type":"original_substantive_source_review","review":"content-amendment-022.json","sources":["https://www.wfhermansvolledigewerken.nl/?verhalen=wittgenstein","https://www.debezigebij.nl/boek/volledige-werken-deel-15-luxe-